-- Demo report templates for the dev profile only (feature 013, slice 10). Loaded together with R__demo_data.sql, which
-- sorts before this file; like the demo ledger it runs only when the Flyway placeholder demoledger is 'on'
-- (integration tests keep it off so the demo cooperative they share has no template).
--
-- One free template, "Відомість земельного податку", with one version, so a chairman can press "Generate" at once.
-- The tax report slot (slot 'TAX') stays EMPTY on purpose: filling it is the first thing the chairman does to try the
-- upload, and an empty slot shows the "no template yet" state of the Reports screen.
-- ON CONFLICT DO NOTHING: whatever the chairman uploads, renames or archives is never overwritten or restored.
--
-- Provenance of the file: generated by SampleTemplates.main (backend/src/test/java/app/nadel/reports/internal),
-- file sample-land-tax-statement.xlsx, 4207 bytes, SHA-256
-- 1e8f904118dc7315c4ee3fe3fbda0ad20b7405eacc5d182f6cd43fb939ba0d53. To regenerate: ./mvnw test-compile, run
-- SampleTemplates.main with the test classpath, then `base64 -i <file> | tr -d '\n'` and paste the result below.
-- The size and the SHA-256 are computed here from the decoded bytes, so they always match the content.
DO $demo_templates$
DECLARE
    demo     uuid := '11111111-1111-1111-1111-111111111111';
    chairman uuid := 'aaaaaaaa-0000-0000-0000-000000000001';
    tpl      uuid := md5('tpl:land-tax')::uuid;
    ver      uuid := md5('tpl:land-tax:v1')::uuid;
    file     bytea := decode('', 'base64');
BEGIN
    IF '${demoledger}' <> 'on' THEN
        RETURN;
    END IF;
    -- The version table is append-only; the owner may insert, and the guard lets a maintenance session through.
    PERFORM set_config('app.ledger_maintenance', 'on', true);

    INSERT INTO report_template (id, tenant_id, slot, name, description, status, created_by)
    VALUES (tpl, demo, NULL, 'Відомість земельного податку',
            'Ділянки з площею, ставкою та сумою земельного податку за обраний період', 'ACTIVE', chairman)
    ON CONFLICT DO NOTHING;

    INSERT INTO report_template_version (id, tenant_id, template_id, version_no, file_name, content, size_bytes,
                                         sha256, uploaded_by)
    SELECT ver, demo, tpl, 1, 'land-tax-statement.xlsx', file, octet_length(file), encode(sha256(file), 'hex'),
           chairman
    WHERE EXISTS (SELECT 1 FROM report_template WHERE id = tpl)
    ON CONFLICT DO NOTHING;

    PERFORM set_config('app.ledger_maintenance', 'off', true);
END
$demo_templates$;
